// static
bool StructTraits<::drive::mojom::File::DataView, ::drive::mojom::FilePtr>::Read(
    ::drive::mojom::File::DataView input,
    ::drive::mojom::FilePtr* output) {
  bool success = true;
  ::drive::mojom::FilePtr result(::drive::mojom::File::New());
  
      if (success && !input.ReadId(&result->id))
        success = false;
      if (success && !input.ReadJustificationText(&result->justification_text))
        success = false;
      if (success && !input.ReadMimeType(&result->mime_type))
        success = false;
      if (success && !input.ReadTitle(&result->title))
        success = false;
      if (success && !input.ReadItemUrl(&result->item_url))
        success = false;
  *output = std::move(result);
  return success;
}

